struct ConfigurationPolitics final:PoliticalTakeoverRead {
 CommonStore& common;std::map<StableId,PoliticalResponsibilityExecution> rows;PoliticalTakeoverApproval approval;
 explicit ConfigurationPolitics(CommonStore& c):common(c){}
 Outcome<PoliticalTakeoverApproval> political_takeover_source(const StableId& id)const override{return id==approval.source.fact_id?Outcome<PoliticalTakeoverApproval>{true,approval,{}}:Outcome<PoliticalTakeoverApproval>{false,{},common_failure("UnknownTestApproval").error};}
 Outcome<std::optional<PoliticalResponsibilityExecution>> find_political_responsibility_for_execution(const PoliticalResponsibilityRef& ref,const WorldIdentity& identity)const override{auto found=rows.find(ref.responsibility_id);if(found==rows.end()||found->second.responsibility.kind!=ref.kind)return {true,std::nullopt,{}};auto out=found->second;out.registration.source_identity=identity;return {true,out,{}};}
 Outcome<PoliticalResponsibilityExecution> political_responsibility_for_execution(const StableId&,const PoliticalResponsibilityRef& ref,const WorldIdentity& identity)const override{auto out=find_political_responsibility_for_execution(ref,identity);if(!out.ok||!out.value)return {false,{},common_failure("MissingTestRegistration").error};return {true,*out.value,{}};}
 Outcome<std::optional<PoliticalResponsibilityExecution>> political_responsibility_before_fact(const PoliticalResponsibilityRef& ref,const StableId& id,Integer,const WorldIdentity& identity)const override{auto out=find_political_responsibility_for_execution(ref,identity);if(!out.ok||!out.value)return out;bool registered=false,decided=false;for(const auto& row:common.state().facts.rows()){if(row.first==out.value->registration_fact_id)registered=true;if(out.value->decision&&row.first==out.value->decision->decision_fact_id)decided=true;if(row.first==id)break;}if(!registered)return {true,std::nullopt,{}};if(!decided){out.value->status=PoliticalResponsibilityExecutionStatus::pending;out.value->decision.reset();out.value->code="PoliticalResponsibilityPending";}return out;}
};
